      "id": 3,
      "claim": "The skull’s smallest transverse dimension (≈140 mm) exceeds the smallest pelvic dimension (≈110 mm) by ~30 mm.",
      "evidence": "Direct subtraction of the measurements from steps 1 and 2.",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Fully fused adult cranial bone is rigid and cannot be compressed enough to reduce its width by ~30 mm without fracturing.",
      "evidence": "Cortical bone yields at ≈130 MPa; compressing a 140 mm skull to <110 mm would require forces far beyond physiological limits and would cause fracture.",
      "weight": 0.15,
      "depends_on": []
    },
